import Foundation
import XCTest

@testable import FORMACore

/// These fixtures are generated by the existing web validator. They establish
/// parity for the first native slice, not support for arbitrary web imports.
final class GoldenParityTests: XCTestCase {
  private var project: URL {
    URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
      .deletingLastPathComponent()
  }

  private func catalog() throws -> [Exercise] {
    try JSONDecoder().decode(
      [Exercise].self,
      from: Data(contentsOf: project.appendingPathComponent("FORMA/Resources/catalog.json")))
  }

  func testCurrentCatalogIncludesLegacyIDsAndExactSelectableCount() throws {
    let exercises = try catalog()
    XCTAssertEqual(exercises.count, 1_711)
    XCTAssertEqual(exercises.filter(\.selectable).count, 1_411)
    XCTAssertEqual(Set(exercises.map(\.id)).count, exercises.count)
    XCTAssertEqual(exercises.first { $0.id == "plank" }?.metric, "load_reps")
    XCTAssertEqual(exercises.first { $0.id == "db-plank" }?.metric, "duration")
  }

  func testEveryCatalogDefaultsCanStartCompleteAndValidateWithItsPublishedUnits() throws {
    let exercises = try catalog()
    for exercise in exercises {
      let d = exercise.defaults
      let prescription = Prescription(
        exerciseId: exercise.id, sets: d.sets, reps: d.reps, weight: d.weight,
        durationSeconds: d.durationSeconds, distanceMeters: d.distanceMeters, perSide: d.perSide)
      let routine = Routine(
        id: "catalog-contract", name: "Synthetic catalog contract", exercises: [prescription])
      var workspace = Workspace(routines: [routine])
      do {
        workspace.active = try WorkoutEngine.start(routine: routine, now: 1_000)
        workspace = try WorkoutEngine.toggleSet(
          in: workspace, entryIndex: 0, setIndex: 0, now: 2_000, catalog: exercises)
        let completed = try WorkoutEngine.finish(workspace, now: 60_000, catalog: exercises)
        try completed.validate(catalog: exercises)
        XCTAssertEqual(WorkoutEngine.completedSets(completed.history[0]), 1, exercise.id)
      } catch {
        XCTFail("Published exercise \(exercise.id) failed its native default contract: \(error)")
      }
    }
  }

  func testWebGeneratedGoldenCorpusMatchesCompletedSetsVolumeAndIndependentUnits() throws {
    let exercises = try catalog()
    let corpus = try JSONDecoder().decode(
      Corpus.self, from: Data(contentsOf: project.appendingPathComponent("Fixtures/parity.json")))
    XCTAssertTrue(corpus.synthetic)
    XCTAssertEqual(corpus.cases.count, 12)
    for fixture in corpus.cases {
      let workspace = fixture.workspace
      try workspace.validate(catalog: exercises)
      let sessions = workspace.history + (workspace.active.map { [$0] } ?? [])
      let completed = sessions.flatMap(\.exercises).flatMap(\.sets).filter(\.done)
      XCTAssertEqual(completed.count, fixture.expected.completedSets, fixture.id)
      XCTAssertEqual(
        sessions.reduce(0) { $0 + WorkoutEngine.volume($1, catalog: exercises) },
        fixture.expected.volume, accuracy: 0.0001, fixture.id)
      XCTAssertEqual(
        completed.reduce(0) { $0 + ($1.durationSeconds ?? 0) }, fixture.expected.durationSeconds,
        accuracy: 0.0001, fixture.id)
      XCTAssertEqual(
        completed.reduce(0) { $0 + ($1.distanceMeters ?? 0) }, fixture.expected.distanceMeters,
        accuracy: 0.0001, fixture.id)
      let roundTrip = try JSONDecoder().decode(
        Workspace.self, from: JSONEncoder().encode(workspace))
      XCTAssertEqual(roundTrip, workspace, fixture.id)
    }
  }

  private struct Corpus: Decodable {
    var synthetic: Bool
    var cases: [Case]
  }
  private struct Case: Decodable {
    var id: String
    var workspace: Workspace
    var expected: Expected
  }
  private struct Expected: Decodable {
    var completedSets: Int
    var volume: Double
    var durationSeconds: Double
    var distanceMeters: Double
  }
}
